const D = { density: .55, scale: 1, energy: .6, speed: 1, sweep: .6, hue: 210, x: .5, y: .5, style: 'prime-glow', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const G = 99, M = G * G, half = (G - 1) / 2, maxRing = half;
const cellPx = 2, R = G * cellPx; // 198

// prime sieve (primes are seed-independent) — build once
if (!S.sieve) {
  const NB = M + 1600;
  const sv = new Uint8Array(NB + 1); sv.fill(1); sv[0] = 0; sv[1] = 0;
  for (let i = 2; i * i <= NB; i++) { if (sv[i]) { for (let j = i * i; j <= NB; j += i) sv[j] = 0; } }
  S.sieve = sv; S.NB = NB;
}
// Ulam spiral walk -> per-integer grid + buffer coords + ring index — build once
if (!S.bx) {
  const bx = new Int16Array(M), by = new Int16Array(M), rg = new Int16Array(M), dg = new Int16Array(M), ad = new Int16Array(M);
  let x = 0, y = 0, dx = 1, dy = 0, seg = 1, pass = 0, steps = 0;
  for (let n = 0; n < M; n++) {
    rg[n] = Math.max(Math.abs(x), Math.abs(y));
    dg[n] = x + y; ad[n] = x - y;
    bx[n] = (x + half) * cellPx; by[n] = (y + half) * cellPx;
    x += dx; y += dy; steps++;
    if (steps === seg) { steps = 0; const ndx = dy, ndy = -dx; dx = ndx; dy = ndy; pass++; if (pass === 2) { pass = 0; seg++; } }
  }
  S.bx = bx; S.by = by; S.rg = rg; S.dg = dg; S.ad = ad;
}
// buffer + accumulation
if (!S.pg || S.R !== R) { S.pg = createGraphics(R, R); S.pg.pixelDensity(1); S.R = R; S.acc = new Float32Array(R * R * 3); }
// seed-dependent offsets (start integer progression + hue phase)
if (S.seedUsed !== P.seed) {
  S.seedUsed = P.seed;
  const fr = i => { const s = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return s - Math.floor(s); };
  S.offBase = Math.floor(fr(1) * 30);
  S.offStep = 17 + Math.floor(fr(2) * 34);
  S.hoff = fr(3) * 0.5;
}

const sieve = S.sieve, NB = S.NB, bxA = S.bx, byA = S.by, rgA = S.rg, dgA = S.dg, adA = S.ad, acc = S.acc, pg = S.pg;
const t = K.t;
const sec = K.section | 0;
const startN = 1 + S.offBase + sec * S.offStep; // restart with a different offset every section
const hb = (P.hue + S.hoff * 60 + sec * 14) % 360;
const expo = 0.5 + P.energy * 0.85 + K.intensity * 0.3 + K.swell * 0.1 + A.rms * 0.6;
const dens = P.density;

// continuous outward-rippling activation waves (uniform speed -> no static window, no wrap flash)
const growRate = 1.5 + P.speed * 1.7;
const ringFreq = 0.34;
const wavePhase = t * growRate * 0.55;
// scanning diagonal highlight (linear phase -> never re-phases)
const sweepRate = 0.5 + P.speed * 1.1, sweepPeriod = 6, sweepAmt = P.sweep;
const sweepPhase = t * sweepRate;
const diagPos = (sec % 2 === 0);

// iq cosine palette (rgb 0..1)
function pal(m) { const hr = hb / 360; return [0.5 + 0.5 * Math.cos(6.2831 * (m + hr)), 0.5 + 0.5 * Math.cos(6.2831 * (m + hr + 0.33)), 0.5 + 0.5 * Math.cos(6.2831 * (m + hr + 0.66))]; }
function thermal(m) { m = Math.max(0, Math.min(1, m)); const r = Math.min(1, m * 2.3); const g = Math.min(1, Math.max(0, m * 2.4 - 1.25)); const b = Math.max(0, 0.65 - Math.abs(m - 0.22) * 2.4) + Math.max(0, m * 2 - 1.7); return [r, g, Math.min(1, b)]; }

const style = P.style;
let amb, primeC = null, compC = null;
if (style === 'phosphor') { amb = [0.0, 0.075, 0.035]; primeC = [0.22, 1.0, 0.38]; compC = [0.05, 0.34, 0.13]; }
else if (style === 'gold') { amb = [0.07, 0.055, 0.02]; primeC = [1.0, 0.78, 0.30]; compC = [0.34, 0.26, 0.08]; }
else if (style === 'thermal') { amb = [0.08, 0.03, 0.12]; }
else if (style === 'blueprint') { amb = [0.05, 0.12, 0.26]; primeC = [0.90, 0.96, 1.0]; compC = [0.18, 0.44, 0.64]; }
else { amb = [0.07, 0.10, 0.19]; compC = [0.13, 0.16, 0.28]; } // prime-glow

// ambient ground fill (frame fills, luminance floor)
const a0 = amb[0], a1 = amb[1], a2 = amb[2];
for (let p = 0, L = R * R; p < L; p++) { const o = p * 3; acc[o] = a0; acc[o + 1] = a1; acc[o + 2] = a2; }

const bassW = A.bass, trebW = A.treble;
for (let n = 0; n < M; n++) {
  const val = startN + n;
  const isP = val <= NB && sieve[val];
  const ringC = rgA[n];
  // outward-rippling ring wave (continuous, uniform speed)
  const wg = 0.5 + 0.5 * Math.sin(ringC * ringFreq - wavePhase);
  // moving diagonal band
  const diag = diagPos ? dgA[n] : adA[n];
  let sp = (diag - sweepPhase) / sweepPeriod; sp = sp - Math.floor(sp);
  const sband = Math.pow(Math.max(0, 1 - Math.abs(sp - 0.5) * 2), 6);
  const sg = sband * sweepAmt * (1 + trebW * 1.4);

  const bx = bxA[n], by = byA[n], oc = (by * R + bx) * 3;
  if (isP) {
    let br = (0.34 + 0.62 * wg + 0.5 * sg) * expo * (0.7 + 0.5 * dens);
    br += bassW * 0.5 * wg + trebW * 0.4 * sg;
    let c0, c1, c2;
    if (style === 'prime-glow') { const c = pal((val % 6) / 6 + 0.03); c0 = c[0]; c1 = c[1]; c2 = c[2]; }
    else if (style === 'thermal') { const c = thermal(ringC / maxRing * 0.55 + wg * 0.7 + sg * 0.4); c0 = c[0]; c1 = c[1]; c2 = c[2]; }
    else { c0 = primeC[0]; c1 = primeC[1]; c2 = primeC[2]; }
    const core = br, nb = br * (0.35 + dens * 0.95) * 0.5;
    // plus-kernel splat (center + 4 neighbours) — upscale smoothing blooms it into a glowing dot
    acc[oc] += c0 * core; acc[oc + 1] += c1 * core; acc[oc + 2] += c2 * core;
    if (bx + 1 < R) { const o = oc + 3; acc[o] += c0 * nb; acc[o + 1] += c1 * nb; acc[o + 2] += c2 * nb; }
    if (bx - 1 >= 0) { const o = oc - 3; acc[o] += c0 * nb; acc[o + 1] += c1 * nb; acc[o + 2] += c2 * nb; }
    if (by + 1 < R) { const o = oc + R * 3; acc[o] += c0 * nb; acc[o + 1] += c1 * nb; acc[o + 2] += c2 * nb; }
    if (by - 1 >= 0) { const o = oc - R * 3; acc[o] += c0 * nb; acc[o + 1] += c1 * nb; acc[o + 2] += c2 * nb; }
  } else {
    // faint composite dot (fills frame texture)
    const f = (0.11 + 0.07 * wg) * (0.4 + 0.7 * dens) * expo;
    if (style === 'prime-glow') { const c = pal((val % 6) / 6 + 0.03); acc[oc] += c[0] * f * 0.55; acc[oc + 1] += c[1] * f * 0.55; acc[oc + 2] += c[2] * f * 0.55; }
    else if (style === 'thermal') { const c = thermal(0.12 + ringC / maxRing * 0.32); acc[oc] += c[0] * f; acc[oc + 1] += c[1] * f; acc[oc + 2] += c[2] * f; }
    else { acc[oc] += compC[0] * f; acc[oc + 1] += compC[1] * f; acc[oc + 2] += compC[2] * f; }
  }
}

// write accumulation to buffer
pg.loadPixels(); const px = pg.pixels;
for (let p = 0, L = R * R; p < L; p++) { const o = p * 3, q = p * 4; px[q] = Math.min(255, acc[o] * 255); px[q + 1] = Math.min(255, acc[o + 1] * 255); px[q + 2] = Math.min(255, acc[o + 2] * 255); px[q + 3] = 255; }
pg.updatePixels();

push();
if (P.alpha >= 100) background(hb, 45, style === 'blueprint' ? 14 : 6);
const cov = Math.max(width, height) * 1.06 * P.scale;
imageMode(CENTER);
if (P.alpha < 100) tint(0, 0, 100, P.alpha);
image(pg, P.x * width, P.y * height, cov, cov);
pop();
